function selectEntries() {
	var url = fullURL + "/items" + queryStringParams(start, count)
	var json

//	java.lang.System.out.println("selectEntries()")

	if (useJSON != null)
		json = useJSON
	else
		json = makeCall(url, "No columns returned from Dataset")

	DSField = new java.util.HashMap()

	for (var o in json)
		if (typeof(json[o]) != "object")
			DSField.put(o, json[o])

	entries = json.items
	id = entries.id
	label = entries.label
	entryCnt = 0
}

function toEntry(thisProp) {
	var e = system.newEntry()

	for (var p in thisProp)
		e[p] = thisProp[p]

	return e
}

function addAttributes(entry, json, depth, attname) {
	var props = json.properties

	if (typeof(attname) == "undefined")
		attname = "?????"

	if (typeof(depth) == "undefined" || depth <= 0) {
		for (var o in json)
			if (typeof(json[o]) != "object")
				entry[o] = json[o]

		depth = 0
	} else {
		if (typeof(json[valueField]) != "undefined")
			entry[attname] = json[valueField]
	}

	if (typeof(props) != "undefined" && props != null) {
		for (var i = 0; i < props.length; i++) {
			thisProp = props[i]

			if (typeof(thisProp[valueField]) == "object") {
				if ("status".equals(thisProp.valueType)) {
					entry[thisProp.id] = toEntry(thisProp)
					var e = entry.getObject(thisProp.id)
					e.value = toEntry(thisProp.value)
				} else
					addAttributes(entry, thisProp[valueField], depth+1, thisProp.id)
			}
			else
			if (typeof(thisProp[valueField]) != "undefined") {
				entry[thisProp.id] = thisProp[valueField]
			}
			else {
				java.lang.System.out.println("addAttributes() - parsing problem: " + toJSON(thisProp))
			}	
		}
	}	
}

function getNextEntry () {
	var p
	var i
	var itr
	var key
	var json
	var val

	if (deBug) java.lang.System.out.println("getNextEntry() - entryCnt: " + entryCnt + "   length: " + entries.length)

	if (entries == null || entryCnt >= entries.length) {
		result.setStatus (0);
		return;
	}

	json = entries[entryCnt]

//	addAttributes(entry, json)

	entryCnt++

	entry["$rowNumber"] = entryCnt
	entry["$totalRows"] = entries.length

	// now add fields from the top-level - the message itself
	itr = DSField.keySet().iterator()
	while (itr.hasNext()) {
		key = itr.next()
		entry["$" + key] = DSField.get(key)
	}	

	// add fields - apart from properties - for this item
	addAttributes(entry, json)

	result.setStatus (1);
	return entry		
}

function getParams() {
	var url = fullURL + "/parameters"
	var json
	var p
	var e
	var params = new java.util.HashMap()

	if (useJSON == null)
		json = makeCall(url, "No parameters returned from Dataset")
	else
		return params

	for (var i = 0; i < json.items.length; i++)  {
		p = json.items[i]
		e = system.newEntry()
		e.id = p.id
		e.label = p.label
		e.type = p.type
		e.description = p.description
		e.required = p.required
		if ( ("!" + p["default"]) != "!undefined" ) 
			e["default"] = p["default"]
		else
			e["default"] = ""

		params.put(p.id, e)
	}		

	return params		
}

function queryStringParams(strt, cnt) {
	var qs = ""
	var itr = params.keySet().iterator()
	var e
	var pval

	itr = params.keySet().iterator()

	while (itr.hasNext()) {
		e = params.get(itr.next())
		pval = connector.getParam(e.id.getValue())
		if (pval && pval != null && pval.trim() != "")
			if (!qs)
				qs = "?param_" + e.id + "=" + pval
			else
				qs += "&param_" + e.id + "=" + pval
	}

	if (conditions && conditions != null && conditions.trim() != "")
		if (!qs)
			qs += "conditions=" + conditions
		else
			qs += "&conditions=" + conditions

	if (typeof(strt) != "undefined" && strt != "")
		qs += "&start=" + strt
	if (typeof(cnt) != "undefined" && cnt != "")
		qs += "&count=" + cnt

    qs += "&properties=all"

	if (qs.startsWith("&"))
		qs = "?" + qs.substring(1)

//java.lang.System.out.println("qs: " + qs)

	return qs
}

function makeCall(uri, errormsg) {
	var httpEntry
	var jsonStr
	var json

	http.setParam("url", uri)
	http.setParam("username", user)
	http.setParam("password", password)
	http.initialize(null)

	httpEntry = system.newEntry();
	httpEntry["http.content-type"] = "application/json"
	httpEntry["http.method"] = "GET"
	httpEntry["http.accept"] = "application/json"

	java.lang.System.out.println("uri: " + uri)

	httpEntry = http.queryReply(httpEntry)	

	jsonStr = httpEntry.getString("http.bodyAsString")

	if (deBug) {
		java.lang.System.out.println(">>Making call to " + uri + "\n<<Received: " + jsonStr)
	}
	// java.lang.System.out.println("json: " + jsonStr)

	jsonString = jsonStr
	connector.setParam("jsonString", jsonString)

	if (jsonStr == null) {
		throw errormsg + " - HTTP return:\n" + httpEntry.toString()
	}	
	else {
		try {
			json = fromJson(jsonStr)
		} catch (ex) {
			throw errormsg + " - Error parsing JSON received: " + ex + "    JSON: " + jsonStr
		}	
//		eval("json=" + jsonStr)
	}	

	if (typeof(json) == "undefined" || json == null) {
		throw errormsg + " - HTTP return:\n" + httpEntry.toString()
	} else
	if (json.msgSeverity)
		throw json.msgText + "\nJSON returned:\n" + jsonStr

	return json
}

//
// Syslogd POC connector. This connector creates a UDP socket
//

debug = true

// syslogd messages are sent on port 514 by default
socket = null;

// datagram packet
packet = null;

// severity codes
severity = [
	"0 Emergency: system is unusable",
	"1 Alert: action must be taken immediately",
	"2 Critical: critical conditions",
	"3 Error: error conditions",
	"4 Warning: warning conditions",
	"5 Notice: normal but significant condition",
	"6 Informational: informational messages",
	"7 Debug: debug-level messages",
];

// facility codes
facility = [
	"0 kernel",
	"1 user",
	"2 mail",
	"3 system daemons",
	"4 security/authorization",
	"5 internal syslogd",
	"6 line printer subsystem",
	"7 network news subsystem",
	"8 UUCP subsystem",
	"9 clock daemon",
	"10 security/authorization messages",
	"11 FTP daemon",
	"12 NTP subsystem",
	"13 log audit (note 1)",
	"14 log alert (note 1)",
	"15 clock daemon (note 2)",
	"16 local0",
	"17 local1",
	"18 local2",
	"19 local3",
	"20 local4",
	"21 local5",
	"22 local6",
	"23 local7",
];

function logmsg(msg) {
	if (debug)
		java.lang.System.out.println(msg)
	try {
		task.logmsg(msg)
	} catch (ex) {
		main.logmsg(msg)
	}	
}

function getPort() {
	var str = connector.getParam("port")
	var port = 0
	try {
		port = java.lang.Integer.parseInt(str)
	} catch (ex) {
		port = 9514
	}
	return port
}

function selectEntries() {
	var port = getPort()
	logmsg("Listening to port " + port)
	socket = new java.net.DatagramSocket(port);

	var buf = new java.io.ByteArrayOutputStream();
	for(i = 0; i< 4096; i++)
		buf.write(0);

	packet = java.net.DatagramPacket(buf.toByteArray(), buf.size());
}

function getNextEntry () {

	// Read next UDP packet
	socket.receive(packet);

	// Create a string from the bytes received
	var str = new java.lang.String(packet.getData(), 0, packet.getLength());

	// Add the packet and the entire string read for good measure
	entry.setAttribute("rawstring", str);
	entry.setAttribute("packet", packet);

	// Parse syslog entry:
	//
	//	<PRI><TIME-STAMP><HOSTNAME><MSG>
	//
	// 	<27>Jul 27 00:30:13 Shelob newsyslog[24155]: logfile turned over
	//
	//

	var index = str.indexOf(">");
	if(index != -1) {
		// Facility and severity (facility (5bits)  + severity(3bits) = priority code)
		var pri = str.substring(1, index);
		var fac = pri >> 3;
		var sev = pri & 7;
		entry.setAttribute("severity", severity[sev]);
		entry.setAttribute("facility", facility[fac]);

		// Timestamp (fixed format: Mmm Dd hh:mm:ss)
		var pos = new java.text.ParsePosition(index+1);
		var tsd = new java.text.SimpleDateFormat("MMMM d HH:mm:ss").parse(str, pos);
		entry.setAttribute("timestamp", tsd);

		// Hostname
		str = str.substring(pos.getIndex()).trim();
		index = str.indexOf(" ");
		entry.setAttribute("host", str.substring(0, index));

		// Message
		entry.setAttribute("message", str.substring(index+1));
	}

}

function querySchema() {
	var fields = ["rawstring", "packet", "host", "message", "severity", "facility"];
	for(f in fields) {
		var e = new com.ibm.di.entry.Entry();
		e.addAttributeValue("name", fields[f]);
		list.add(e);
	}		
	result.setStatus (1);
}

function terminate() {
	if(socket != null) {
		socket.close();
		socket = null;
	}
}

