}


/**
 * Adds user to SAM group. NOTE! The group needs to be in SAM.
 * @param groupId group ID in SAM
 * @param userId User's ldap id
 * @return True if success, false if errors
 */
function manageGroupMembers(userId, members){
	var grp;
	var userList = new java.util.ArrayList();
	var notHandled = new java.util.ArrayList();
	var exceptions = new java.util.ArrayList();
	var operations = new java.util.ArrayList();

	userList.add(userId);

	if (typeof(members) != "undefined" && members != null && members.size() > 0) {
		var modify = members.getOperation().equals("modify");

		for (var i = members.size(); i--;) {
			var groupId = members.getValue(i)
			var deleteFromGroup = modify && members.getValueOperation(i).equals("delete")

			try {
				grp = rgyRegistry.getGroup(tamDomain, groupId);

				if (grp === null) {
					throw msgGroupNotFound + ": " + groupId
				} else
				if (deleteFromGroup) {
					grp.removeMembers(userList);
				} else {
					grp.addMembers(userList);
				}	
			} catch (ex) {
				// ignore HPDAA0330E   An attribute type or attribute value specified already exists in the entry.
				if (ex.toString().indexOf("HPDAA0330E") < 0) {
					notHandled.add(groupId)
					exceptions.add(ex)
					if (deleteFromGroup) {
						operations.add(resource.getString("delete from"));
					} else {
						operations.add(resource.getString("add to"));
					}
				}	
			}	
		}	
	}

	if(notHandled.size() > 0) {
		logmsg("WARN", resource.getString("The following group memberships were not handled for User" + ": " + userId));
		for(var i=0; i < notHandled.size(); i++) {
			logmsg("WARN", "   -> " + operations.get(i) + " " + groupLabel + ": " + notHandled.get(i) + "  - error: " + exceptions.get(i))
		}
	}

}

/**
 * This method gets a member attribute value and determines if it is
 * an LDAP DN. If so, then it extracts the RDN value and returns this
 */
function fixPrincipalName(name) {
	if (typeof(name) == "undefined" || name == null) {
		return ""
	}

	try {
		rdns = new javax.naming.ldap.LdapName(name).getRdns();
		name = rdns.get(rdns.size()-1).getValue();
	} catch (ex) {
		// not a DN
	}

	return name;
}

/**
 * Adds users found in member attribute to SAM group. 
 * NOTE: This Connector handles value operation tags.
 * @param groupId group ID in SAM
 * @param userId User's ldap id
 * @return True if success, false if errors
 */
function manageMembership(groupId, member){
	var grp;
	var userList = new java.util.ArrayList();
	var size;
	var notHandled = new java.util.ArrayList();
	var exceptions = new java.util.ArrayList();
	var operations = new java.util.ArrayList();

	if (typeof(member) == "undefined" || member === null) {
		return;
	}

	size = member.size();

	grp = rgyRegistry.getGroup(tamDomain, groupId);

	if (grp === null) {
		throw resource.getString("Group does not exist") + ": " + groupId;
	}

	for (var i = 0; i < size; i++) {
		try {
			userList.clear();
			userList.add(fixPrincipalName(member.getValue(i)));
			if ("delete".equals(member.getValueOperation(i))) {
				grp.removeMembers(userList);
			} else {
				grp.addMembers(userList);
			}
		} catch (ex) {
			notHandled.add(userList.get(0))
			exceptions.add(ex)
			if ("delete".equals(member.getValueOperation(i))) {
				operations.add(resource.getString("removing member"));
			} else {
				operations.add(resource.getString("adding member"));
			}
		}	
	}	

	if(notHandled.size() > 0) {
		logmsg("WARN", resource.getString("The following memberships were not handled for Group") + ": " + groupId);
		for(var i=0; i < notHandled.size(); i++) {
			logmsg("WARN", "   -> " + operations.get(i) + ": " + notHandled.get(i) + "  - error: " + exceptions.get(i))
		}
	}
}

function terminate(){
	if(rgyRegistry != null) {
		rgyRegistry.close();
	}
	currententry = null;
	list = null;
	rgiRegistry = null;
}

function createUser(mDN, mCN, mSN, mPassword, mDesc, secAcctValid, secPwdValid, groups)
{
	var pwdValid = typeof(mPassword) != "undefined" && mPassword != null && mPassword.trim().length > 0;
	var pwdBytes = null;

	if (pwdValid) {
		pwdBytes = mPassword.trim().split('');
	}

	mDesc = mDesc || "";

	var attrs = rgyRegistry.newRgyAttributes();

    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.SEC_DN_NAME, mDN);
    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.COMMON_NAME_NAME,mCN);
    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.SURNAME_NAME, mSN);
    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.DESCRIPTION_NAME, mDesc);
	attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.SEC_ACCT_VALID_NAME, boolValue(secAcctValid, true));
    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.SEC_PWD_VALID_NAME, boolValue(secPwdValid, true));

    rgyRegistry.createUser(tamDomain, mCN, mDN, pwdBytes, false, attrs, null);

    manageGroupMembers(mCN, groups)
}

function createGroup(mGroupDN, mCN, mDesc, mMember)
{
	var attrs = rgyRegistry.newRgyAttributes();

	mDesc = mDesc || "";

//	attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.SEC_ACCT_VALID_NAME, boolValue(secAcctValid));
    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.SEC_DN_NAME, mGroupDN);
    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.COMMON_NAME_NAME,mCN);
    attrs.putAttribute(com.tivoli.pd.rgy.RgyAttributes.DESCRIPTION_NAME, mDesc);

	rgyRegistry.createGroup(tamDomain, mCN, mGroupDN, attrs);

	if (typeof(mMember) != "undefined" && mMember != null) {
		manageMembership(mCN, mMember)
	}
}


function putEntry()
{
	var doCreate = false;
	var dn = entry.getString("secDN");
	var name = entry.getString(nameAtt)
	var cn = entry.getString("cn");
	var sn = entry.getString("sn")
	var desc = entry.getString("description");
	var groups = entry.getAttribute("memberOf");
	var member = entry.getAttribute("member");
	if (member === null) {
		member = entry.getAttribute("uniqueMember");
	}
	var secPwdValid = entry.getString("secPwdValid");
	var secAcctValid = entry.getString("secAcctValid");
	var userPassword = entry.getString("userPassword");
	var pwdValid = typeof(userPassword) != "undefined" && userPassword != null && userPassword.trim().length > 0;
	var pwdBytes = null;

	if (pwdValid) {
		pwdBytes = userPassword.trim().split('');
	}

	var attMissingMsg = resource.getString("Mandatory attribute missing from Output Map for") + " ";
	if(dn == null ) {
		throw attMissingMsg + entityTypeName + ": secDN";
	}

	if(name == null ) {
		throw attMissingMsg + entityTypeName + ": " + nameAtt;
	}	

	try {
		if (entityType == "User") {
			importUser(dn, name, groups, secAcctValid, pwdValid);
			var entity = rgyRegistry.getUser(tamDomain, name);
			if (pwdValid) {
			   	entity.setPassword(pwdBytes);
			}	
		}	
		else {
			importGroup(dn, name, member);
		}	

	 }
	catch(e)
	{
		// This Check is for if User/Group is NOT present in TDS
		if((e.message.indexOf("HPDMG0755W") >= 0) || (e.message.indexOf("HPDMG1068E") >= 0)) {
			doCreate = true;
		}
		else {
			throw e;
	   	}	
	}	

	if(doCreate == true) {
		if(entityType == "User") {
			if(sn == null) {
				throw "Mandatory attribute missing from Output Map: sn";
			}	
			createUser(dn, name, sn, userPassword, desc, secAcctValid, pwdValid, groups);
		}
		else {
			//Group create
			createGroup(dn, name, desc, member);
		}
	}
}


function modEntry()
{
	var name = old.getString(nameAtt);
	var sn = entry.getString("sn")
	var desc = entry.getString("description");
	var secPwdValid = entry.getString("secPwdValid");
	var secAcctValid = entry.getString("secAcctValid");
	var userPassword = entry.getString("userPassword");
	var groups = entry.getAttribute("memberOf");
	var member = entry.getAttribute("member");
	if (member === null) {
		member = entry.getAttribute("uniqueMember");
	}
	var pwdValid = typeof(userPassword) != "undefined" && userPassword != null && userPassword.trim().length > 0;
	var entity
	var pwdBytes = null;

	if (pwdValid) {
		pwdBytes = userPassword.trim().split('');
	}

	if(name == null) {
		throw "No entry found to modify.";
	}

	if (entityType == "User") {
		entity = rgyRegistry.getUser(tamDomain,name);

		if (entity) {
	   	    entity.attributeReplace(com.tivoli.pd.rgy.RgyAttributes.SEC_PWD_VALID_NAME, boolValue(secPwdValid, true));
		    entity.attributeReplace(com.tivoli.pd.rgy.RgyAttributes.SEC_ACCT_VALID_NAME, boolValue(secAcctValid, true));

			if (typeof(desc) != "undefined" && desc != null) {
				entity.attributeReplace(com.tivoli.pd.rgy.RgyAttributes.DESCRIPTION_NAME, desc);
			}

			if (typeof(sn) != "undefined" && sn != null) {
				entity.attributeReplace(com.tivoli.pd.rgy.RgyAttributes.SURNAME_NAME, sn);
			}

			if (pwdValid) {	
		   	    entity.setPassword(pwdBytes);
			}

			if (typeof(groups) != "undefined" && groups != null) {
				manageGroupMembers(name, groups)
			}
		}	
	}
	else {
		//replace Attributes for Group -- only description supported
		entity = rgyRegistry.getGroup(tamDomain,name);

		if (entity) {
			if (typeof(desc) != "undefined" && desc != null) {
				entity.attributeReplace(com.tivoli.pd.rgy.RgyAttributes.DESCRIPTION_NAME, desc);
			}

			if (typeof(member) != "undefined" && member != null) {
				manageMembership(name, member)
			}
		}	
	}
}

function deleteEntry () {
	if(entry == null || entry.size() == 0) {
		throw "No entry found using specified Link Criteria. Nothing to delete."
	}

	var name = entry.getString(nameAtt);

	if(name == null) {
		throw "Naming attribute '" + nameAtt + "' not found in " + entityType + " entry. Cannot delete.";
	}

	if (entityType =="User") {
		deleteUser(name, delFromRegistry);
	}
	else {	
	 	deleteGroup(name, delFromRegistry);
	}	
}

function findEntry () {
	var finalsearch = null;
	var readEntry

	for (var i = 0; i< search.size(); i++) {
		var attrname = search.getCriteria(i).name.toLowerCase().trim();
		var match = search.getCriteria(i).match;
		var value = search.getCriteria(i).value;
		var negate = search.getCriteria(i).negate;

		if(negate) {
			throw "Negate not supported for Link Criteria !";
		}

		if(!attrname.equalsIgnoreCase(nameAtt))	{
			throw "This connector only supports searching for '" + nameAtt + "' attribute for " + entityType;
		}	
		if(match != search.EXACT && match != search.INITIAL_STRING && match != search.FINAL_STRING && match != search.SUBSTRING) {
			throw "This connector only supports the following operators: Equals, Contains, starts With & ends With";
		}	
		var searchString = value;
		if(match == search.INITIAL_STRING) {
			searchString+="*";
		}
		else if (match == search.FINAL_STRING) {
			searchString="*"+searchString;			
		}
		else if (match == search.SUBSTRING) {
			searchString="*"+searchString+"*";			
		}

		selectEntries(searchString);
		var currentsearch = new java.util.HashMap();

		do {
			try {
				getNextEntry(list);
			} catch (e)	{
				if(e.message.indexOf("HPDAA0271E") >= 0) {
//					entriesNotInLDAPtoDelete.add(value, "")
					entry.setAttribute(nameAtt, value)
				}
			}
			if(entry.size() > 0) {
				readEntry = system.newEntry()
				readEntry.merge(entry)
				currentsearch.put(entry.getString(nameAtt), readEntry);
			}
		} while (entry.size() > 0);

		if(finalsearch == null) {
			finalsearch = currentsearch;
		}
		else {
			var keys = finalsearch.keySet().toArray();
			for(var key in keys) {
				if ((search.getType() == search.SEARCH_AND) && (!currentsearch.containsKey(key)) && (finalsearch.containsKey(key))) {
					finalsearch.remove(key);
				}
				else
				if ((search.getType() == search.SEARCH_OR) && (currentsearch.containsKey(key)) && (!finalsearch.containsKey(key))) {
					finalsearch.put(key, currentsearch.get(key));
				}
			}
		}
	}
	if(finalsearch == null)	{
		throw "No Link Criteria defined !";
	}
	var keys = finalsearch.keySet().toArray();
	java.util.Arrays.sort(keys);
	if (keys.length == 0) {
		result.setStatus(0);
	}
	else {
		result.setStatus(1);
		entry.removeAllAttributes();
		entry.merge(finalsearch.get(keys[0]));
		for (var i=1; i<keys.length; i++) {
			var key = keys[i];
			connector.addFindEntry(finalsearch.get(key));
		}
	}
}

function schemaItem(name, sntx) {
	var e = system.newEntry()
	e.name = name
	e.setAttribute("syntax", sntx)
	return e
}

function querySchema() {
	list.add(schemaItem("secDN", "String"))
	list.add(schemaItem(nameAtt, "String"))

	if (entityType.equals("User")) {
		list.add(schemaItem("secAcctValid", "Boolean"))
		list.add(schemaItem("secPwdValid", "Boolean"))
		list.add(schemaItem("cn", "String"))
		list.add(schemaItem("sn", "String"))
		list.add(schemaItem("description", "String"))
		list.add(schemaItem("memberOf", "Multi-valued String"))
		list.add(schemaItem("userPassword", "String"))
	} else {
		list.add(schemaItem("description", "String"))
		list.add(schemaItem("member","Multi-valued String"))
	}
	result.setStatus(1)
}

