	apiKey = getParam("apikey", false);
	returnas = getParam("returnas", false);
	pagesize = getParam("pagesize", false);
	deBug = "true".equals(getParam("deBug", false));
	permissionMap = getParam("permissionMap", false);
	if(permissionMap != null) {
		loadPermissionMap(permissionMap);
	}

	if (returnas == null) { returnas = "flat"; } 

	if (!system.isValidInt(pagesize)) {
		// not a valid number
		pagesize = 100;
	} else {
		pagesize = pagesize*1.0;
	}

	// prepare base URL
	var usePort = "";
	if (port != null && !"80".equals(port)) {
		usePort = ":" + port;
	}
//	baseurl = "https://" + user + ":" + apiKey + "@" + host + usePort + "/rest/v3/";
	baseurl = "https://" + host + usePort + "/rest/v3/";

	// verify that this is a SoftLayer service
	verifySoftLayer();

	initialized = true;
}	

function selectEntries() {
	list = null;
	listCnt = 0;
	totalCnt = 0;
	startkey = "";

	list = makeRequest({verb : "GET", 
						url : baseurl + "SoftLayer_Account/getUsers.json", 
						where : "selectEntries"});

}

function getNextEntry() {
	if (typeof entry === "undefined" || entry === null) { entry = system.newEntry(); } 
	if (list !== null && listCnt < list.length) {
		var item = list[listCnt];
		listCnt++;
		totalCnt++;
		var hEntry = item2Entry(item);
		entry.merge(hEntry);
		result.setStatus(1);
		return entry;
	} else {
		result.setStatus(0);
		return null;
	}
}

function putEntry() {
	var item = entry2SLObject(entry);
	var reply = makeRequest({verb : "POST",
							 url : baseurl + "SoftLayer_User_Customer.json",
							 body : '{"parameters":[' + toJson(item) + ',"' + tempPassword + '"]}',
							 where : "putEntry"});

	entry["$response"] = reply;
	entry["$id"] = reply.id;

	// -- Update user permissions
	updateSLPermissions(reply.id, entry[groupMemberAttribute]);
}

function findEntry() {
	var foundEntry, matchEntry, key, itr;
	var matches = new java.util.concurrent.ConcurrentHashMap();

	current = system.newEntry();

	// get all users
	selectEntries();

	do {
		foundEntry = getNextEntry();

		if (foundEntry !== null) {
			if (matchFound(search, foundEntry)) {
				matchEntry = system.newEntry();
				matchEntry.merge(foundEntry);
				matches.put(foundEntry.id, matchEntry);
			}
		}	
	} while (foundEntry !== null);

	if (matches.size() == 0) {
		result.setStatus(0);
		return null;
	} else
	if (matches.size() == 1) {
		result.setStatus(1);
		key = matches.keySet().toArray()[0];
		entry.merge(matches.get(key));
		current.merge(entry);
		return entry;
	} else {
		result.setStatus(1);
		itr = matches.keySet().iterator();
		while (itr.hasNext()) {
			key = itr.next();
			connector.addFindEntry(matches.get(key)); 
		}
		return matches;
	}
}

function modEntry() {
	var item = entry2SLObject(entry);
	// -- these props cannot be modified
	delete item.id;
	delete item.parentId;
	var reply = makeRequest({verb : "PUT",
							 url : baseurl + "SoftLayer_User_Customer/" + current.id + "/setObject.json",
							 body : '{"parameters":[' + toJson(item) + ']}',
							 where : "modEntry"});

	// -- Update user permissions
	updateSLPermissions(current.id, entry[groupMemberAttribute]);
}

function deleteEntry() {
	var item = entry2SLObject(entry);
	var reply = makeRequest({verb : "DELETE",
							 url : baseurl + "SoftLayer_User_Customer/" + current.id + ".json",
							 where : "deleteEntry"});
}


// -- Update user permissions
function updateSLPermissions(id, memberof) {
	if(memberof != null && memberof.size() > 0) {
		var key = memberof.getValue();
		if(memberof.getOperation() == "delete") {
			removeSLPermission(id, groupPermissionMap[key])
		} else {
			addSLPermission(id, groupPermissionMap[key])
		}
	}
}

function addSLPermission(id, permissions) {
	// http://sldn.softlayer.com/reference/services/SoftLayer_User_Customer/addBulkPortalPermission
	makeRequest({verb : "POST",
		 url : baseurl + "SoftLayer_User_Customer/" + id + "/addBulkPortalPermission.json",
		 body : '{"parameters":[' + toJson(permissions) + ']}',
		 where : "addSLPermission"}
	);
}

function removeSLPermission(id, permissions) {
	// http://sldn.softlayer.com/reference/services/SoftLayer_User_Customer/removeBulkPortalPermission
	makeRequest({verb : "POST",
		 url : baseurl + "SoftLayer_User_Customer/" + id + "/removeBulkPortalPermission.json",
		 body : '{"parameters":[' + toJson(permissions) + ']}',
		 where : "addSLPermission"}
	);
}

function terminate() {
	resetConnector();

	try {
		http.terminate();
	} catch (ex) {
		// do nothing
	}
}

// CouchDB Script connector
//
// 
//var version = "20140526 1237" // started
//var version = "20140614 2300" // replace host/port with url parameter
