		query = params.quary	
	}

	var reply = makeRequest({"verb" : "GET", 
							 "url" : "/query?q=" + query, 
							 "ctype" : "application/json", 
							 "where" : "selectEnries"});

	if (typeof reply.rows !== "undefined") {
		var rows = reply.rows;
		for (var i = 0; i < rows.length; i++) {
			resultSet.add(GrcObjectToEntry(rows[i]));
		}
	} else {
		resultSet.add(GrcObjectToEntry(reply));
