// result set handler - works similar to an Iterator			
var resultSet = {
	set : new java.util.ArrayList(),
	index : 0,
	nextUrl : null,

	add : function(entry) {
		var setEntry = system.newEntry();
		setEntry.merge(entry);
		this.set.add(setEntry);
	},

	size : function() {
		return this.set.size();
	},

	clear : function() {
		this.set.clear();
		this.index = 0;
	},

	hasNext : function() {
		return (this.set !== null && (this.index < this.set.size() || this.nextUrl != null));
	},

	next : function() {
		if (this.set === null) {
			return null;
		} else {
			//if no results AND no next link, end of list
			if(this.index >= this.set.size() && this.nextUrl == null){
				return null;
			}
			//else if no results but have next link, get result set
			else if(this.index >= this.set.size() && this.nextUrl != null){
				this.getResultSet();
			}	

			//return next entry
			return this.set.get(this.index++);
		}
	},

	getResultSet : function() {
		var reply = makeRequest({"verb" : "GET", 
						"url" : "/"+this.nextUrl, 
						"ctype" : "application/json", 
						"where" : "selectEnries"});
		if (typeof reply.rows !== "undefined") {
			var rows = reply.rows;
			for (var i = 0; i < rows.length; i++) {
				resultSet.add(GrcObjectToEntry(rows[i]));
			}
			} else {
				resultSet.add(GrcObjectToEntry(reply));
		}

		//check for next link
		if (typeof reply.links !== "undefined") {
			resultSet.nextUrl = null;
			for (var i = 0; i < reply.links.length; i++) {
				if(reply.links[i].rel == "next"){
					resultSet.nextUrl = reply.links[i].href;
				}
			}
		}
	}
}

