// parameters container object
var params = {	url : "", 
				username : "", 
				password : "",
				object : "",
				query : "",

				refresh : function(connector) {
					for (var pname in this) {
						if (typeof this[pname] !== "function") {
							this[pname] = connector.getParam(pname);
						}	
					}
				},

				apply : function(http) {
