// result set handler - works similar to an Iterator			
var resultSet = {
	set : new java.util.ArrayList(),
	index : 0,

	add : function(entry) {
		var setEntry = system.newEntry();
		setEntry.merge(entry);
		this.set.add(setEntry);
	},

	size : function() {
		return this.set.size();
	},

	clear : function() {
		this.set.clear();
		this.index = 0;
	},

	hasNext : function() {
		return (this.set !== null && this.index < this.set.size());
	},

	next : function() {
		if (this.set === null || this.index >= this.set.size()) {
			return null;
		} else {
			return this.set.get(this.index++);
		}
	}
